"""Build the vendor registry from the real BPI Challenge 2019 data."""

import yaml

from bpi.log import load_bpi
from protocol.loader import PROJECT_ROOT

OUTPUT_FILE = PROJECT_ROOT / "data" / "vendors_bpi.yaml"

HEADER = """\
# Vendor registry built from the BPI Challenge 2019 event log
# (B.F. van Dongen, 4TU.ResearchData, doi:10.4121/uuid:d06aff4b-79f0-45e6-8ec8-e19730c248f1).
# Vendor IDs and names are the dataset's anonymised values.
# Bank accounts are FAKE: the dataset has none, so one is generated per vendor.
# Generated by: python -m bpi.make_vendors  (do not edit by hand)
"""


def build_vendors():
    """Return the vendor registry, and the set of vendors that had more than one name."""
    log = load_bpi(["case Vendor", "case Name"]).dropna()
    pairs = log.value_counts()   # how often each (vendor, name) pair appears, most frequent first

    names = {}
    multi_name = set()
    for (vendor_id, name), count in pairs.items():
        if vendor_id not in names:
            names[vendor_id] = name        # first seen = most frequent name
        else:
            multi_name.add(vendor_id)      # this vendor appears with another name too

    vendors = {}
    for number, vendor_id in enumerate(sorted(names), start=1):
        vendors[vendor_id] = {"name": names[vendor_id], "account": f"FAKE-BPI-{number:04d}"}
    return vendors, multi_name


if __name__ == "__main__":
    vendors, multi_name = build_vendors()
    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        f.write(HEADER)
        yaml.safe_dump({"vendors": vendors}, f, sort_keys=False)
    print(f"Wrote {len(vendors)} vendors to {OUTPUT_FILE}")
    print(f"Vendors with more than one name in the log: {len(multi_name)}")